def hide_results_of_delayed_mocks(apps, schema_editor):
    # Papers already set to give results after time now hide them in their mock
    # contest instead of holding submissions back. Scores of past attempts are
    # unaffected: hidden problems only leave the public score.
    ContestProblem = apps.get_model("judge", "ContestProblem")
    ContestSubmission = apps.get_model("judge", "ContestSubmission")
    ExamPaper = apps.get_model("judge", "ExamPaper")
    contests = ExamPaper.objects.filter(
        mock_delayed=True, mock_contest__isnull=False
    ).values("mock_contest_id")
    ContestProblem.objects.filter(contest_id__in=contests).update(is_result_hidden=True)
    ContestSubmission.objects.filter(problem__contest_id__in=contests).update(
        is_result_hidden=True
    )


